import{_ as a,o as s,c as t,a6 as i}from"./chunks/framework.CKIbuWFA.js";const k=JSON.parse('{"title":"性能と処理量の上限","description":"","frontmatter":{"title":"性能と処理量の上限","docId":"developer.performance","translationKey":"developer.performance","locale":"ja","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"04bc0a89b86724872adae3ab8ddc8e29f5517dad14d51bc103d917582cf289ae","translationRevision":"ef2e12b148f544f8d9e13e814a3be66aa2a81d6100477f8ef740e9812dbe4dd3","order":110},"headers":[],"relativePath":"ja/developer/performance.md","filePath":"ja/developer/performance.md","lastUpdated":1794611623000}'),r={name:"ja/developer/performance.md"};function n(o,e,l,d,p,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="performance-and-bounded-work" tabindex="-1">性能と処理量の上限 <a class="header-anchor" href="#performance-and-bounded-work" aria-label="Permalink to &quot;性能と処理量の上限 {#performance-and-bounded-work}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>イベント計上と終了処理を維持しつつ、具体的なボトルネックを測ります。固定ビルド、決定的入力、分離プロファイルで始めます。フィード高速化と永続化の信頼性を混同しないよう<a href="./events.html">イベント</a> を読みます。過去のベンチマークは指定ビルドと端末の観測で、現行製品の保証ではありません。</p><h2 id="measure-the-right-boundary" tabindex="-1">適切な境界を測る <a class="header-anchor" href="#measure-the-right-boundary" aria-label="Permalink to &quot;適切な境界を測る {#measure-the-right-boundary}&quot;">​</a></h2><p>デスクトップの outbox は欠落を許す表示と信頼性が必要な応答を分離します。スナップショットはまとめられますが、信頼側のあふれは明確に失敗させます。LIVE 取り込み、プラグイン処理、プロセッサー呼び出し、自動化受付はそれぞれ上限を持ちます。1つの待機列を増やすと、次段へメモリー負荷や遅延が移る場合があります。</p><p>フロントエンドは開発時、または <code>VITE_TIKTOOLS_DIAGNOSTICS=1</code> ビルドで集計診断を公開します。描画行数、フレーム間隔の百分位、保留中の制御呼び出し、画像、所有タイマーを含みます。WebView により JavaScript ヒープ情報は得られない場合があります。非表示ページとホスト可視性は表示の関心を制御し、業務計上は変えません。</p><h2 id="run-a-focused-comparison" tabindex="-1">対象を絞って比較する <a class="header-anchor" href="#run-a-focused-comparison" aria-label="Permalink to &quot;対象を絞って比較する {#run-a-focused-comparison}&quot;">​</a></h2><ol><li>ビルドリビジョン、環境、イベント構成、画像の有無、表示タブ、時間を記録します。</li><li>同じフィクスチャーと計測期間で基準を取ります。</li><li>境界を1つ変え、処理量、p95/p99 遅延、待機列の破棄、欠落、保持メモリー、終了時の排出を比較します。</li><li>遅いプラグイン・受信側と飽和した待機列も含めます。アイドル時の測定ではバックプレッシャーを検査できません。</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live-feed-state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persistence,native-tiktok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live_throughput</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>ネイティブ測定の前に機能要件を確認します。通常の対象単体検査に実際の TikTok 接続は不要です。実装の根拠として <code>crates/tiktools-core/tests/live_throughput.rs</code> とデスクトップ outbox のテストを使います。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>上限付きの投影と受付経路、カウンター、欠落報告は実装されています。<a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/services/points/queue.rs" target="_blank" rel="noreferrer">現在の順序付き書き込み器</a> はメモリー変更前に飽和書き込みを拒否し、同期書き込みへの代替を禁止します。過去の性能報告は既に置き換わった順序不具合を記述します。UI メモリーの上限だけから完全な正しさを推測せず、現行実装・テストでキャッシュ上限と復旧を評価します。</p><h2 id="recover" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;問題が起きたとき {#recover}&quot;">​</a></h2><p>フレームが改善しても計上の健全性が悪化したら境界の変更を戻し、書き込み・受付結果を調べます。非表示タブのタイマー増加は<a href="./lifecycle.html">ライフサイクルの後始末</a> を確認します。生入力数、受付数、損失の分類を報告に残します。欠落から表示は復旧できても、拒否・結果不明になった実処理は直せません。</p>`,14)])])}const u=a(r,[["render",n]]);export{k as __pageData,u as default};
